sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || !newValue) return;
    var start = g_form.getValue('loan_start');
    if (!start) return;

    var MAX_MONTHS = 3;
    var startDate = new Date(getDateFromFormat(start, g_user_date_format));
    var dueDate = new Date(getDateFromFormat(newValue, g_user_date_format));

    var limit = new Date(startDate.getTime());
    limit.setMonth(limit.getMonth() + MAX_MONTHS);   // e.g. 15 Jan -> 15 Apr

    if (dueDate > limit) {
        g_form.showFieldMsg('due_date', 'Loans over ' + MAX_MONTHS + ' months need manager sign-off.', 'info');
    } else {
        g_form.hideFieldMsg('due_date');
    }
}
